'use client'

import * as React from 'react'

import { useOffscreen } from './use-reduced-motion'
import './light-beams.css'

export type LightBeamsProps = React.ComponentPropsWithoutRef<'div'> & {
    /** Number of beams. */
    count?: number
    /** Beam colour. */
    color?: string
    /** Seconds per sway. */
    speed?: number
    paused?: boolean
}

const LightBeams = ({ count = 5, color = 'rgba(167, 139, 250, 0.5)', speed = 8, paused = false, className, style, children, ...props }: LightBeamsProps) => {
    const ref = React.useRef<HTMLDivElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <div
        ref={ref}
        className={['rad-fx-beams', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-beam-color': color, '--rad-fx-beam-speed': `${speed}s`, ...style } as React.CSSProperties}
        {...props}
    >
        <div className="rad-fx-beams-rig" aria-hidden="true">
            {Array.from({ length: count }, (_, i) => {
                const position = count === 1 ? 50 : 10 + (80 / (count - 1)) * i
                return <span
                    key={i}
                    className="rad-fx-beam"
                    style={{ left: `${position}%`, '--rad-fx-beam-tilt': `${(position - 50) * 0.5}deg`, animationDelay: `${-i * 1.3}s` } as React.CSSProperties}
                />
            })}
        </div>
        <div className="rad-fx-beams-content">{children}</div>
    </div>
}

export default LightBeams

/* LightBeams: stage lights shining down from the top edge, gently swaying. */
.rad-fx-beams {
    position: relative;
    isolation: isolate;
    overflow: hidden;
}

.rad-fx-beams-rig {
    position: absolute;
    inset: 0;
    z-index: -1;
    pointer-events: none;
    filter: blur(6px);
}

.rad-fx-beam {
    position: absolute;
    top: -10%;
    width: 9%;
    height: 130%;
    margin-left: -4.5%;
    transform-origin: 50% 0;
    background: linear-gradient(to bottom, var(--rad-fx-beam-color), transparent 85%);
    clip-path: polygon(42% 0, 58% 0, 100% 100%, 0 100%);
    animation: rad-fx-beam-sway var(--rad-fx-beam-speed, 8s) ease-in-out infinite alternate;
}

.rad-fx-beams[data-state='paused'] .rad-fx-beam { animation-play-state: paused; }

.rad-fx-beams-content { position: relative; }

@keyframes rad-fx-beam-sway {
    from { transform: rotate(calc(var(--rad-fx-beam-tilt, 0deg) - 8deg)); opacity: 0.6; }
    to { transform: rotate(calc(var(--rad-fx-beam-tilt, 0deg) + 8deg)); opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-beam { animation: none; transform: rotate(var(--rad-fx-beam-tilt, 0deg)); }
}

[data-rad-fx-motion='reduce'] .rad-fx-beam { animation: none; transform: rotate(var(--rad-fx-beam-tilt, 0deg)); }
